            let mut cov = CMatrix::zeros(n_mics, n_mics);
            for i in 0..n_mics {
                for j in 0..=i {
                    let sum: Cplx = bin_slices[i]
                        .iter()
                        .zip(bin_slices[j])
                        .map(|(a, b)| a * b.conj())
                        .sum();
                    cov[(i, j)] = sum;
