use std::time::Instant;
use nalgebra::DMatrix;
use musicrs::MusicEstimator;
fn t<F: FnMut()>(name:&str, n:usize, mut f:F){ for _ in 0..20 {f();} let t0=Instant::now(); for _ in 0..n {f();} println!("{name:40} {:8.1} us", t0.elapsed().as_secs_f64()*1e6/n as f64); }
fn main(){
  let mut r = hound::WavReader::open("/home/orchid/projects/musicrs/tests/data/single-source/single-source_1400Hz_40deg_1.0s.wav").unwrap();
  let raw: Vec<i32> = r.samples::<i32>().map(Result::unwrap).collect();
  let data = DMatrix::from_fn(4, raw.len()/4, |c,t| raw[t*4+c] as f64 / 8388608.0);
  let est = MusicEstimator::default();
  let rows: Vec<Vec<f64>> = (0..4).map(|m| data.row(m).iter().copied().collect()).collect();
  if std::env::args().nth(1).as_deref()==Some("ifb") { t("ifb 1 bin only", 3000, || { std::hint::black_box(est.ifb_music_spectrum(&data,160,1,Some(&[14])).unwrap()); }); return; }

  type C = nalgebra::Complex<f64>;

  t("A1 amax only", 500, || { std::hint::black_box(data.amax()); });
  t("A2 manual max-abs loop", 500, || { let mut m=0.0f64; for x in data.iter() { if !x.is_finite() {panic!()} m = m.max(x.abs()); } std::hint::black_box(m); });
  t("A3 data / 2.0 (alloc 512KB)", 500, || { std::hint::black_box(&data / 2.0); });
  t("A4 vec![0;64000] + fill", 500, || { let mut v = vec![0.0f64; 64000]; for (o,x) in v.iter_mut().zip(data.iter()) { *o = x*0.5; } std::hint::black_box(v); });
  t("B2 row copies via slice stride", 500, || { let s = data.as_slice(); for m in 0..4 { let r: Vec<f64> = s[m..].iter().step_by(4).copied().collect(); std::hint::black_box(r); } });
  t("A normalise copy + amax", 500, || { std::hint::black_box(&data / data.amax()); });
  t("B row copies x4", 500, || { for m in 0..4 { let r: Vec<f64> = data.row(m).iter().copied().collect(); std::hint::black_box(r); } });
  t("C new FftPlanner + plan 160", 500, || { let mut p = rustfft::FftPlanner::<f64>::new(); std::hint::black_box(p.plan_fft_forward(160)); });
  let stfts: Vec<Vec<Vec<C>>> = rows.iter().map(|r| musicrs::stft(r,160,0).unwrap()).collect();
  t("D strongest power", 500, || { let mut p = vec![0.0;81]; for mic in &stfts { for (pp,b) in p.iter_mut().zip(mic) { *pp += b.iter().map(|c| c.norm_sqr()).sum::<f64>()/100.0; } } std::hint::black_box(p); });
  let mut cov = nalgebra::DMatrix::<C>::zeros(4,4);
  t("E cov 1 bin (nalgebra allocs)", 500, || { let mut c = nalgebra::DMatrix::<C>::zeros(4,4); for w in 0..100 { let col = nalgebra::DVector::from_iterator(4, stfts.iter().map(|s| s[14][w])); c += &col * col.adjoint(); } cov = c.scale(0.01); std::hint::black_box(&cov); });
  t("F noise_subspace(real cov)", 500, || { std::hint::black_box(est.noise_subspace(&cov,1).unwrap()); });
  let nm = est.noise_subspace(&cov,1).unwrap();
  t("G spectrum", 500, || { std::hint::black_box(est.spectrum(&nm,1400.0).unwrap()); });
  t("H ln + exp 720", 500, || { let (s,_) = est.spectrum(&nm,1400.0).unwrap(); let v: Vec<f64> = s.iter().map(|x| (x.ln()).exp()).collect(); std::hint::black_box(v); });
  t("ifb 1 bin", 500, || { std::hint::black_box(est.ifb_music_spectrum(&data,160,1,Some(&[14])).unwrap()); });
  t("ifb 80 bins", 200, || { let b:Vec<usize>=(1..=80).collect(); std::hint::black_box(est.ifb_music_spectrum(&data,160,1,Some(&b)).unwrap()); });
  t("narrowband", 500, || { std::hint::black_box(est.estimate_doa_from_real(&data,1,1400.0).unwrap()); });
  t("public stft x4 (complex fft, Vec<Vec>)", 500, || { for r in &rows { std::hint::black_box(musicrs::stft(r,160,0).unwrap()); } });
  let mut planner = rustfft::FftPlanner::<f64>::new(); let fft = planner.plan_fft_forward(160);
  t("complex fft x400 in place, no alloc", 500, || { let mut b = vec![rustfft::num_complex::Complex::new(0.0,0.0);160]; for r in &rows { for w in r.chunks_exact(160) { for (o,x) in b.iter_mut().zip(w) { *o = (*x).into(); } fft.process(&mut b); } std::hint::black_box(&b); } });
  let rf = realfft::RealFftPlanner::<f64>::new().plan_fft_forward(160);
  t("real fft x400, no alloc", 500, || { let mut i = rf.make_input_vec(); let mut o = rf.make_output_vec(); let mut s = rf.make_scratch_vec(); for r in &rows { for w in r.chunks_exact(160) { i.copy_from_slice(w); rf.process_with_scratch(&mut i,&mut o,&mut s).unwrap(); } std::hint::black_box(&o); } });
  // one-bin DFT directly (Goertzel-like dot product)
  t("direct DFT of bin 14 only x400", 500, || { let tw: Vec<(f64,f64)> = (0..160).map(|n| { let a = -2.0*std::f64::consts::PI*14.0*n as f64/160.0; (a.cos(), a.sin()) }).collect(); let mut acc=0.0; for r in &rows { for w in r.chunks_exact(160) { let (mut re, mut im)=(0.0,0.0); for (x,(c,s)) in w.iter().zip(&tw) { re+=x*c; im+=x*s; } acc+=re+im; } } std::hint::black_box(acc); });
  let cov = nalgebra::DMatrix::<nalgebra::Complex<f64>>::identity(4,4);
  t("noise_subspace + spectrum (1 bin)", 500, || { let n = est.noise_subspace(&cov,1).unwrap(); std::hint::black_box(est.spectrum(&n,1400.0).unwrap()); });
}

