use std::time::Instant;
use nalgebra::{DMatrix, Complex};
use musicrs::MusicEstimator;
type C = Complex<f64>;
fn t<R, F: FnMut() -> R>(name:&str, n:usize, mut f:F){ for _ in 0..20 {std::hint::black_box(f());} let t0=Instant::now(); for _ in 0..n {std::hint::black_box(f());} println!("{name:44} {:8.1} us", t0.elapsed().as_secs_f64()*1e6/n as f64); }
fn lanes(v:&[f64]) -> f64 { let mut m=[0.0f64;8]; let mut b=[0.0f64;8]; let (ch,tail)=v.as_chunks::<8>(); for c in ch { for ((m,b),&x) in m.iter_mut().zip(&mut b).zip(c) { let a=x.abs(); *m = if a>*m {a} else {*m}; *b += x*0.0; } } for ((m,b),&x) in m.iter_mut().zip(&mut b).zip(tail) { let a=x.abs(); *m = if a>*m {a} else {*m}; *b+=x*0.0;} assert!(!b.iter().any(|x| x.is_nan())); m.into_iter().fold(0.0,f64::max) }
fn serial(v:&[f64]) -> f64 { let mut m=0.0f64; for &x in v { if !x.is_finite() {panic!()} m=m.max(x.abs()); } m }
fn scaled_rows(d:&DMatrix<f64>, f:f64) -> Vec<Vec<f64>> { let mut rows = vec![Vec::with_capacity(d.ncols()); d.nrows()]; for c in d.as_slice().chunks_exact(d.nrows()) { for (r,&x) in rows.iter_mut().zip(c) { r.push(x*f); } } rows }
fn main(){
  let mut r = hound::WavReader::open("/home/orchid/projects/musicrs/tests/data/single-source/single-source_1400Hz_40deg_1.0s.wav").unwrap();
  let raw: Vec<i32> = r.samples::<i32>().map(Result::unwrap).collect();
  let data = DMatrix::from_fn(4, raw.len()/4, |c,t| raw[t*4+c] as f64 / 8388608.0);
  let est = MusicEstimator::default();
  println!("== whole calls");
  t("narrowband (estimate_doa_from_real)", 1000, || est.estimate_doa_from_real(&data,1,1400.0).unwrap());
  t("ifb 1 bin", 1000, || est.ifb_music_spectrum(&data,160,1,Some(&[14])).unwrap());
  let all: Vec<usize> = (1..=80).collect();
  t("ifb 80 bins", 300, || est.ifb_music_spectrum(&data,160,1,Some(&all)).unwrap());
  for k in [1usize, 2, 5, 10, 20, 40, 80] { let b: Vec<usize> = (1..=k).collect(); t(&format!("ifb bins 1..={k}"), 300, || est.ifb_music_spectrum(&data,160,1,Some(&b)).unwrap()); }
  for k in [10usize, 20] { let b: Vec<usize> = (14..14+k).collect(); t(&format!("ifb bins 14..14+{k}"), 300, || est.ifb_music_spectrum(&data,160,1,Some(&b)).unwrap()); }
  println!("== shared preprocessing");
  t("max-abs + finite: serial f64::max fold", 1000, || serial(data.as_slice()));
  t("max-abs + finite: 8 lanes", 1000, || lanes(data.as_slice()));
  t("old: nalgebra data / scale (copy)", 1000, || &data / 2.0);
  t("old: data.row(m) copies x4", 1000, || (0..4).map(|m| data.row(m).iter().copied().collect::<Vec<f64>>()).collect::<Vec<_>>());
  t("scaled_rows (one pass)", 1000, || scaled_rows(&data, 0.5));
  t("alt: zeroed rows + strided writes", 1000, || { let s = data.as_slice(); let nr = data.nrows(); (0..nr).map(|i| { let mut r = vec![0.0; data.ncols()]; for (o,x) in r.iter_mut().zip(s[i..].iter().step_by(nr)) { *o = x*0.5; } r }).collect::<Vec<_>>() });
  let rows = scaled_rows(&data, 1.0);
  println!("== narrowband");
  let n = rows[0].len();
  let mut cplan = rustfft::FftPlanner::<f64>::new();
  let (ff, fi) = (cplan.plan_fft_forward(n), cplan.plan_fft_inverse(n));
  t("analytic signal x4 (complex FFT + IFFT)", 300, || { rows.iter().map(|r| { let mut b: Vec<C> = r.iter().map(|&x| C::new(x,0.0)).collect(); ff.process(&mut b); for x in &mut b[1..n/2] { *x *= 2.0; } for x in &mut b[n/2+1..] { *x = C::new(0.0,0.0);} fi.process(&mut b); b }).collect::<Vec<_>>() });
  let z: Vec<Vec<C>> = rows.iter().map(|r| musicrs::analytic_signal(r)).collect();
  t("covariance Z Z^H over 16000 samples", 300, || { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..=i { let s: C = z[i].iter().zip(&z[j]).map(|(a,b)| a*b.conj()).sum(); c[(i,j)]=s; c[(j,i)]=s.conj(); } } c });
  let rp = realfft::RealFftPlanner::<f64>::new().plan_fft_forward(n);
  let mut rows2 = rows.clone();
  t("real FFT x4 (in place of FFT+IFFT)", 300, || { let mut s = rp.make_scratch_vec(); rows2.iter_mut().map(|r| { let mut o = rp.make_output_vec(); rp.process_with_scratch(r,&mut o,&mut s).unwrap(); o }).collect::<Vec<_>>() });
  let sp: Vec<Vec<C>> = rows.iter().map(|r| { let mut r = r.clone(); let mut o = rp.make_output_vec(); rp.process(&mut r,&mut o).unwrap(); o }).collect();
  t("Parseval covariance over 8001 bins", 1000, || { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..=i { let s: C = sp[i][1..8000].iter().zip(&sp[j][1..8000]).map(|(a,b)| a*b.conj()).sum(); c[(i,j)]=s; c[(j,i)]=s.conj(); } } c });
  t("new real FFT plan for 16000 (uncached)", 300, || realfft::RealFftPlanner::<f64>::new().plan_fft_forward(n));
  let cov = { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..4 { c[(i,j)] = z[i].iter().zip(&z[j]).map(|(a,b)| a*b.conj()).sum::<C>() / n as f64; } } c };
  t("noise_subspace (faer Hermitian eig, 4x4)", 3000, || est.noise_subspace(&cov,1).unwrap());
  let nm = est.noise_subspace(&cov,1).unwrap();
  t("spectrum, 720 angles", 2000, || est.spectrum(&nm,1400.0).unwrap());
  for f in [100.0, 1400.0, 4000.0, 7900.0] { t(&format!("spectrum at {f} Hz"), 2000, || est.spectrum(&nm,f).unwrap()); }
  t("720 x 4 from_polar only", 2000, || { let mut s = C::new(0.0,0.0); for k in 0..720 { let th = k as f64 * 0.0087266; for p in &est.antenna_positions { s += C::from_polar(1.0, 2.0*std::f64::consts::PI*1400.0*(p[0]*th.cos()+p[1]*th.sin())/343.2); } } s });
  println!("== ifb");
  t("stft x4, real FFT, nfft 160", 1000, || rows.iter().map(|r| musicrs::stft(r,160,0).unwrap()).collect::<Vec<_>>());
  let st: Vec<Vec<Vec<C>>> = rows.iter().map(|r| musicrs::stft(r,160,0).unwrap()).collect();
  t("old: complex FFT, new Vec per window x4", 1000, || { let f = cplan.plan_fft_forward(160); let mut res = vec![vec![C::new(0.0,0.0);100];81]; for r in &rows { for (w,c) in r.chunks_exact(160).enumerate() { let mut b: Vec<C> = c.iter().map(|&x| C::new(x,0.0)).collect(); f.process(&mut b); for k in 0..81 { res[k][w]=b[k]; } } } res });
  t("power of every bin (silence reference)", 1000, || { let mut p = vec![0.0;81]; for m in &st { for (pp,b) in p.iter_mut().zip(m) { *pp += b.iter().map(|c| c.norm_sqr()).sum::<f64>()/100.0; } } p });
  t("old: cov 1 bin via nalgebra outer products", 3000, || { let mut c = DMatrix::<C>::zeros(4,4); for w in 0..100 { let col = nalgebra::DVector::from_iterator(4, st.iter().map(|s| s[14][w])); c += &col * col.adjoint(); } c });
  t("cov 1 bin, direct sums", 3000, || { let mut c = DMatrix::<C>::zeros(4,4); for i in 0..4 { for j in 0..=i { let s: C = st[i][14].iter().zip(&st[j][14]).map(|(a,b)| a*b.conj()).sum(); c[(i,j)]=s; c[(j,i)]=s.conj(); } } c });
}

